BLOQUES['test_cf_rev6_dia1'] = '#!/usr/bin/env python3\n"""test_cf_rev6_dia1 - BE-CF21 (CFA #2284 rev6, 3-nov): false positives / gaps the day-1 gate (U-114..U-125) found in CFA rev5.\nEach case: the real error still fails; the false positive no longer does. U-117 reads existing_walls[] tag_ids and the canon\ntags_descartados; U-120 looks only at the markup Wall ID (not keynotes / sheets of the source); markups_demo: area = Polygon,\na bent polyline = one piece per axis; R80e.84 allows the DELIVERED image (proceso/review_img) in Review Items."""\nimport os, sys, tempfile\nsys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))\nimport chequeos_biblioteca as CB\nimport markups_demo as MD\nimport plantilla_excel as PE\nfrom PIL import Image\nd = tempfile.mkdtemp()\npng = os.path.join(d, "PT0001.png")\nImage.new("RGB", (40, 40), (255, 0, 0)).save(png)\noc = [{"id": "PT0001", "type": "W6", "sheet": "A-202", "png": png, "png_verificado": True, "kind": "partition_tag"},\n      {"id": "PT0002", "type": "W6", "sheet": "A-202", "png": png, "png_verificado": True, "kind": "partition_tag"}]\ninv = {"ocurrencias": {"partition_tag": oc}}\nwalls = [{"id": "M1", "element": "wall", "tag_ids": []}]\nok = {"walls": walls, "existing_walls": [{"id": "W6-01-CB", "tag_ids": ["PT0001"]}],\n      "tags_descartados": [{"id": "PT0002", "motivo": "legend text of the WALL TYPE SCHEDULE (not a plan tag)"}]}\nr = CB.u_117(CB.B(canon=ok, inv_full=inv))\nassert r[0] == "PASS", r\nmal = {"walls": walls, "existing_walls": [{"id": "W6-01-CB", "tag_ids": ["PT0001"]}]}\nassert CB.u_117(CB.B(canon=mal, inv_full=inv))[0] == "FAIL"\na_ok = [{"label": "A-202", "subject": "BOARD ONLY", "tipo": "PolyLine", "verts": [(0, 0), (50, 0)],\n         "contents": "BOARD ONLY - NO FRAMING \\u00b7 7.90 LF \\u00b7 H 14 ft \\u00b7 G.2/A-202 + A-622 D3/D4 \\u00b7 KN3 + KN4 \\u00b7 W6-01S-SRV"}]\nr = CB.u_120(CB.B(annots=a_ok))\nassert r[0] == "PASS", r\na_mal = [dict(a_ok[0], contents="BOARD ONLY \\u00b7 7.90 LF \\u00b7 A-202 \\u00b7 W6-01 & W6-02")]\nassert CB.u_120(CB.B(annots=a_mal))[0] == "FAIL"\na_l = [dict(a_ok[0], verts=[(0, 0), (50, 0), (50, 50)])]\nassert CB.u_120(CB.B(annots=a_l))[0] == "FAIL"\nassert MD.es_area({"polyline": [[0, 0], [10, 0], [10, 10], [0, 10], [0, 0]], "h_ft": 0, "group": "ceilings"})\nassert not MD.es_area({"polyline": [[0, 0], [10, 0]], "h_ft": 12})\npz = MD.piezas_por_eje([(0, 0), (80, 0), (80, 150)])\nassert len(pz) == 2 and pz[0][-1] == pz[1][0], pz\nassert len(MD.piezas_por_eje([(0, 0), (80, 0), (160, 0)])) == 1\nimport openpyxl\nwb = openpyxl.Workbook()\nws = wb.active\nws.title = "Review Items"\nws["F3"] = "proceso/review_img/r02_S241_A2.png"\nassert not PE.verificar_texto_cliente(wb), PE.verificar_texto_cliente(wb)\nws["F4"] = "img_rev4/r02.png"\nassert PE.verificar_texto_cliente(wb)\ndel ws["F4"]\nws2 = wb.create_sheet("Scope Checklist")\nws2["B2"] = "proceso/review_img/r02.png"\nassert PE.verificar_texto_cliente(wb)\nprint("test_cf_rev6_dia1 OK")\n'
BLOQUES['test_cf_rev7_burbujas'] = '#!/usr/bin/env python3\n"""test_cf_rev7_burbujas - BE-CF22 (CFA #2284 rev7, 4-nov): gaps the v81cf33 gate showed on CFA.\n(1) CE_CALLOUTS CALLOUT only took 1-char labels: \'A3/A-601\', \'C4/A-624\', \'D1-A/A-625\' were never seen as citations;\n(2) a printed reference to a view that does not exist, declared with its RFI in callouts_no_aplican -> AMBER (reported), not FAIL;\n(3) revision_materiales: \'1/2\\" SHEATHING\' without material = SHEATHING (per wall notes), not regular gyp -> AMBER, not RED;\n(4) BE-VS-13 summed the DEMO markup of the existing board (DEMO-14 <wall>) into the board SF of that wall."""\nimport os, sys\nsys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))\nimport chequeos_biblioteca as CB\nimport revision_materiales as RV\nassert ("A3", "A601") in CB.callouts_de("elev A3/A-601") and ("D1-A", "A625") in CB.callouts_de("D1-A/A-625")\nassert ("C4", "A624") in CB.callouts_de("framing per C4/A-624") and ("1", "A202") in CB.callouts_de("1/A-202")\nassert not CB.callouts_de("G.3/A-202 KN10/A-050 2.5.B/A-909")\nassert RV.tipo_board(\'1/2" SHEATHING\') == "SHEATHING" and RV.tipo_board(\'1/2" gyp sheathing\') == "REG"\nassert RV.tipo_board(\'1/2" cementitious board\') == "CEMENT"\nb = CB.B(pt=[{"fila": 9, "wall": "EX-1", "lf": 10.0, "h": 6.0, "board": 60.0}],\n         annots=[{"label": "A-202", "subject": "BOARD ONLY", "contents": "BOARD ONLY \\u00b7 10.00 LF \\u00b7 60.00 SF board \\u00b7 EX-1"},\n                 {"label": "A-202", "subject": "DEMO", "contents": "DEMO \\u00b7 10.00 LF \\u00b7 60.00 SF \\u00b7 DEMO-14 EX-1"}])\nassert CB.be_vs_13(b)[0] == "PASS", CB.be_vs_13(b)\nb2 = CB.B(pt=b.pt, annots=[b.annots[0], dict(b.annots[0])])\nassert CB.be_vs_13(b2)[0] == "FAIL"\nprint("test_cf_rev7_burbujas OK")\n'
BLOQUES['test_cf_rev8_no_cargado'] = '#!/usr/bin/env python3\n"""test_cf_rev8_no_cargado - BE-CF23 (CFA rev7 -> rev8, 4-nov): RFI-27 (drive-thru furr down) was open with \'Plans: nothing loaded\'\nand CB_U_116 passed. U-048: an open RFI carries the conservative value LOADED with its delta."""\nimport os, sys\nsys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))\nimport chequeos_biblioteca as CB\nmal = {"rfis": [{"id": "RFI-27", "status": "open - conservative value loaded",\n                 "opciones": {"A": {"texto": "Plans: nothing loaded (no depth printed)", "delta": "0"}}}]}\nok = {"rfis": [{"id": "RFI-27", "status": "open - conservative value loaded",\n                "opciones": {"A": {"texto": "Plans: furr down 11 LF x 2\'-0 assumed loaded (conservative)", "delta": "per 6 in: 5.5 SF"}}}]}\ncerrado = {"rfis": [{"id": "RFI-09", "status": "closed - estimator decision (option A)", "opciones": {"A": {"texto": "not loaded per GC"}}}]}\ncel = [("Scope Checklist", "B2", "x")]\nassert CB.u_116(CB.B(canon=mal, celdas=cel))[0] == "FAIL", CB.u_116(CB.B(canon=mal, celdas=cel))\nassert CB.u_116(CB.B(canon=ok, celdas=cel))[0] == "PASS", CB.u_116(CB.B(canon=ok, celdas=cel))\nassert CB.u_116(CB.B(canon=cerrado, celdas=cel))[0] == "PASS"\nprint("test_cf_rev8_no_cargado OK")\n'
BLOQUES['test_cf_rev9_auditoria'] = '#!/usr/bin/env python3\n"""test_cf_rev9_auditoria - BE-CF24 (CFA rev8 -> rev9, coordination audit 4-nov):\n(1) CE_COPIA_LIMPIA: a clean copy that loses a page XObject fails; same content passes (U-051);\n(2) BE-CF24: a board-only Source whose \'| height: ... = N ft\' differs from the loaded height fails (#0);\n(3) R-ALC-06: a DEMO markup on a sheet that is not a demolition plan fails."""\nimport os, sys, tempfile\nsys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))\nimport pymupdf\nimport chequeos_biblioteca as CB\nimport compuerta_entrega as CE\nd = tempfile.mkdtemp()\no, ok, mal = (os.path.join(d, n) for n in ("o.pdf", "ok.pdf", "mal.pdf"))\ndoc = pymupdf.open(); p = doc.new_page(width=200, height=200)\nimg = pymupdf.Pixmap(pymupdf.csRGB, pymupdf.IRect(0, 0, 20, 20), False); img.clear_with(0)\np.insert_image(pymupdf.Rect(20, 20, 180, 180), pixmap=img); doc.save(o)\ndoc2 = pymupdf.open(o); doc2.save(ok)\ndoc3 = pymupdf.open(); doc3.new_page(width=200, height=200); doc3.save(mal)\nassert CE.copia_limpia(o, ok)[0] == [], CE.copia_limpia(o, ok)\nassert CE.copia_limpia(o, mal)[0], "a copy without the image must fail"\ne_ok = {"id": "X-1", "height_ft": 1.25, "source": "W6/A-202 | height: [CONFIRMED] C3/A-604 prints 1\' - 3\\" = 1.25 ft | elev A1/A-602"}\ne_mal = {"id": "X-2", "height_ft": 1.25, "source": "W6/A-202 | height: G.3/A-202 1/2\\" cement board to 1\'-0\\" = 1.0 ft [CONFIRMED]"}\nassert CB.be_cf24(CB.B(canon={"existing_walls": [e_ok]}))[0] == "PASS"\nassert CB.be_cf24(CB.B(canon={"existing_walls": [e_mal]}))[0] == "FAIL"\nan = [{"label": "A-202", "subject": "DEMO", "contents": "DEMO"}, {"label": "A-050", "subject": "DEMO", "contents": "DEMO"}]\nhj = {"A-202": "DIMENSIONAL FLOOR PLAN", "A-050": "DEMOLITION PLAN"}\nassert CB.r_alc_06(CB.B(annots=an, hojas=hj))[0] == "FAIL"\nassert CB.r_alc_06(CB.B(annots=an[1:], hojas=hj))[0] == "PASS"\nprint("test_cf_rev9_auditoria OK")\n'
BLOQUES['test_cf_rev10_busqueda'] = '#!/usr/bin/env python3\n"""test_cf_rev10_busqueda - BE-CF25 (CFA rev9 -> rev10, user 5-nov \'no estan impresos, tienes que buscarlo hasta encontrarlo\'):\nrev9 left RFI-11 / RFI-12 / RFI-20 open as \'printed nowhere\' after an 8-term grep of one GC set. A \'not printed\' RFI needs the full\nhunt: all sheets, >= 12 terms, both GC sets, vector measurement at the printed scale, >= 3 places checked with images."""\nimport os, sys\nsys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))\nimport chequeos_biblioteca as CB\nrev9 = {"rfis": [\n    {"id": "RFI-11", "status": "open - conservative value loaded", "question": "Dining half walls to demolish (A-050 KN8): height printed nowhere.",\n     "barrido": {"hojas": "ALL", "terminos": ["HALF WALL", "HALF WALLS", "PONY", "KNEE", "LOW WALL", "42\\"", "3\'-6\\"", "PARTIAL HEIGHT"]}},\n    {"id": "RFI-12", "status": "open - conservative value loaded", "question": "Existing menuboard furr-down: drop and extent printed nowhere.",\n     "barrido": {"hojas": "ALL", "terminos": ["MENU", "MENUBOARD", "FURR", "FURR DOWN", "FURR-DOWN", "BULKHEAD", "BULK HEAD", "DROP"]}},\n    {"id": "RFI-20", "status": "open - conservative value loaded", "question": "Draftstop patch: the patch size is printed nowhere.",\n     "barrido": {"hojas": "ALL", "terminos": ["DRAFTSTOP", "DRAFT STOP", "DRAFTSTOPPING", "CHASE", "BEVERAGE", "CONDUIT", "SLEEVE", "PENETRAT", "PATCH"]}}]}\nr = CB.be_cf25(CB.B(canon=rev9))\nassert r[0] == "FAIL" and len(r[1]) == 3, r\nconflicto = {"rfis": [{"id": "RFI-26", "status": "open", "question": "D2/A-622 prints 10\'-2\\" and A-221 prints 10\'-0\\": which?", "barrido": {}}]}\nassert CB.be_cf25(CB.B(canon=conflicto))[0] == "PASS"\nprint("test_cf_rev10_busqueda OK")\n'
BLOQUES['test_cf_rev10_rfi_resuelto'] = '#!/usr/bin/env python3\n"""test_cf_rev10_rfi_resuelto - BE-CF26 (CFA rev10): RFI-28 se resolvio en 34.57 SF (A-052 a escala) pero la opcion A seguia\ndiciendo \'38.35 SF loaded\' y daba 34.57 como alternativa. Un RFI resuelto habla desde el valor cargado."""\nimport os, sys\nsys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))\nimport chequeos_biblioteca as CB\nmal = {"rfis": [{"id": "RFI-28", "status": "resolved - from drawings", "resolved": {"answer": "= 34.57 SF [DERIVED]"},\n                 "opciones": {"A": {"texto": "Plans: 38.35 SF loaded (largest outline)", "delta": "0 (loaded); 35.39 SF reading: -2.96 SF; 34.57 SF hatch outline: -3.78 SF"}}}]}\nr = CB.be_cf26(CB.B(canon=mal))\nassert r[0] == "FAIL" and len(r[1]) == 2, r\nbien = {"rfis": [{"id": "RFI-28", "status": "resolved - from drawings", "resolved": {"answer": "= 34.57 SF [DERIVED]"},\n                  "opciones": {"A": {"texto": "Plans: 34.57 SF loaded", "delta": "0 (loaded); outer outlines: 35.39 SF +0.82 SF, 38.35 SF +3.78 SF"}}}]}\nassert CB.be_cf26(CB.B(canon=bien))[0] == "PASS"\nabierto = dict(mal); abierto["rfis"] = [dict(mal["rfis"][0], status="open")]\nassert CB.be_cf26(CB.B(canon=abierto))[0] == "PASS"\nprint("test_cf_rev10_rfi_resuelto OK")\n'
BLOQUES['test_cf_rev11_demo_sf'] = '#!/usr/bin/env python3\n"""test_cf_rev11_demo_sf - U-143 (usuario 5-nov): CFA rev10 cargaba los walls a demoler como LF x H x 2 layer(s) (doble SF).\nDemolicion = SF del elemento (wall LF x H, cielo area), sin capas ni materiales; RFI de capas de demo = FAIL."""\nimport os, sys\nsys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))\nimport chequeos_biblioteca as CB\nrev10 = {"misc_items": [{"ref": "DEMO-01", "familia": "demolition - gypsum board and metal framing", "unit": "SF", "qty": 412.736,\n                         "op": "16.733 LF x 12.333 ft x 2 layer(s) = 412.736 SF"},\n                        {"ref": "DEMO-C1", "familia": "demolition - gypsum board and metal framing", "unit": "SF", "qty": 89.95,\n                         "op": "A-052 vector 11.244 x 8.0 ft = 89.95 SF x 1 layer"}],\n         "demo_geom": [{"id": "DEMO-01", "layers": 2, "sf": 412.736}]}\nr = CB.u_143(CB.B(canon=rev10))\nassert r[0] == "FAIL" and len(r[1]) == 3, r\nrev11 = {"misc_items": [{"ref": "DEMO-01", "familia": "demolition - gypsum board and metal framing", "unit": "SF", "qty": 206.37,\n                         "op": "16.733 LF x 12.333 ft = 206.37 SF (wall area)"},\n                        {"ref": "DEMO-C1", "familia": "demolition - gypsum board and metal framing", "unit": "SF", "qty": 89.95,\n                         "op": "A-052 vector 11.244 x 8.0 ft = 89.95 SF (ceiling area)"}],\n         "demo_geom": [{"id": "DEMO-01", "layers": 1, "sf": 206.37}]}\nassert CB.u_143(CB.B(canon=rev11))[0] == "PASS"\nrfi = {"rfis": [{"id": "RFI-02", "question": "Existing walls to demolish: number of gypsum board layers per face?"}]}\nassert CB.u_143(CB.B(canon=rfi))[0] == "FAIL"\nprint("test_cf_rev11_demo_sf OK")\n'
for nombre, codigo in BLOQUES.items():
    ns = {"__name__": "__main__", "__file__": os.path.join(AQUI, nombre + ".py")}
    exec(compile(codigo, nombre, "exec"), ns)
